/**
 * Per-member project mutes: which projects a member has asked not to hear about.
 */
import { and, asc, eq, inArray, sql } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** The member's muted projects, oldest mute first. */
export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .orderBy(asc(sql`${projectMutes.rowid}`))
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Which of `userIds` have muted `projectId`; the fan-out asks once per event. */
export async function listUsersMutingProject(
  orgId: OrgId,
  projectId: ProjectId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: projectMutes.userId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
        inArray(projectMutes.userId, [...userIds]),
      ),
    )
    .all();
  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

/** Idempotent: muting an already-muted project is a no-op, not a conflict. */
export async function addProjectMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();
}

export async function removeProjectMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}
EOF

