/**
 * Muting a project is personal: it filters what the muting member receives
 * (in-app, email, digest) and never touches anyone else or the webhooks.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as emailService from "@/server/services/email-service";
import * as issueService from "@/server/services/issue-service";
import {
  listMutedProjectIds,
  listNotifications,
  muteProject,
  notify,
  unmuteProject,
} from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, ProjectId } from "@/types/common";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let second: ProjectId;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("mute", "growth");
  other = await createTenant("mute-other", "growth");
  second = (
    await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.owner,
      color: "#6366f1",
      targetDate: null,
    })
  ).id;
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

const payload = (projectId: ProjectId | null) => ({
  title: "t",
  body: "b",
  href: "/issues/x",
  actorId: null,
  projectId,
});

async function inbox(recipient: Tenant["userIds"]["member"], kind: NotificationKind) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: [kind],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("muteProject / unmuteProject / listMutedProjectIds", () => {
  it("mutes only for the actor, idempotently, and can be lifted", async () => {
    await muteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    await muteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    await muteProject(tenant.actors.viewer, tenant.org.id, second);

    expect(await listMutedProjectIds(tenant.actors.viewer, tenant.org.id)).toEqual([
      tenant.project.id,
      second,
    ]);
    expect(await listMutedProjectIds(tenant.actors.admin, tenant.org.id)).toEqual([]);

    await unmuteProject(tenant.actors.viewer, tenant.org.id, second);
    await unmuteProject(tenant.actors.viewer, tenant.org.id, second);
    expect(await listMutedProjectIds(tenant.actors.viewer, tenant.org.id)).toEqual([
      tenant.project.id,
    ]);

    await unmuteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    expect(await listMutedProjectIds(tenant.actors.viewer, tenant.org.id)).toEqual([]);
  });

  it("rejects an org outside the actor's organization", async () => {
    await expect(
      muteProject(tenant.actors.member, other.org.id, other.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      unmuteProject(tenant.actors.member, other.org.id, other.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      listMutedProjectIds(tenant.actors.member, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("rejects a project that does not exist in the org", async () => {
    await expect(
      muteProject(tenant.actors.member, tenant.org.id, other.project.id),
